<script setup>
import { publicAsset } from '../utils/assets.js'
import AnimatedContent from '../components/AnimatedContent.vue'
import { usePageMotion } from '../composables/usePageMotion'
const motionRoot = usePageMotion()
import { computed, nextTick, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { Copy, Download, ArrowUpRight, ShoppingBag, Boxes, Check, MessageSquareText, Send, CheckCheck } from 'lucide-vue-next'
import { products } from '../data/site'
import { useLocale } from '../composables/useLocale'
import EditorialCardHeader from '../components/EditorialCardHeader.vue'
import PageHero from '../components/PageHero.vue'
import StoreLinks from '../components/StoreLinks.vue'
import ContactNavigation from '../components/ContactNavigation.vue'
const { t, tx } = useLocale(), route = useRoute()
const stepIcons = [MessageSquareText, Send, CheckCheck]
const name = ref(''), email = ref(''), company = ref(''), quantity = ref(''), message = ref(''), interest = ref(''), consent = ref(false)
const ready = ref(false), copyState = ref(''), summary = ref(null), firstField = ref(null)
watch(() => route.query.interest, value => { if (['0', '1', '2', '3'].includes(value)) interest.value = value }, { immediate: true })
const selectedProduct = computed(() => products.find(p => p.handle === route.query.product))
const draft = computed(() => [t('contact.draft'), '', ...[['name', name.value], ['email', email.value], ['company', company.value], ['interest', t('contact.types')[Number(interest.value)]], ['quantity', quantity.value], ['message', message.value]].map(([key, value]) => `${t(`contact.${key}`)}: ${value || t('contact.empty')}`), ...(selectedProduct.value ? [`${t('common.collection')}: ${tx(selectedProduct.value.name)}`] : [])].join('\n'))
async function prepare() { ready.value = true; copyState.value = ''; await nextTick(); summary.value?.focus() }
async function edit() { ready.value = false; await nextTick(); firstField.value?.focus() }
async function copy() { try { await navigator.clipboard.writeText(draft.value); copyState.value = 'copied' } catch { copyState.value = 'copyError' } }
function download() { const url = URL.createObjectURL(new Blob([draft.value], { type: 'text/plain;charset=utf-8' })); const a = document.createElement('a'); a.href = url; a.download = 'DLIM-HOME-enquiry.txt'; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
</script>
<template><main ref="motionRoot" id="main-content"><ContactNavigation /><PageHero page="contact" image="dining"><a href="#enquiry" class="button button-dark">{{ t('common.enquire') }}</a></PageHero>
<section id="stores" class="section-space section-muted"><div class="container">
 <AnimatedContent :stagger="0.08" class="section-heading"><p class="eyebrow">{{ t('business.label') }}</p><h2>{{ t('business.title') }}</h2><p class="lead">{{ t('business.intro') }}</p></AnimatedContent>
 <AnimatedContent :stagger="0.08" class="contact-paths">
  <article class="contact-path"><div class="contact-path-top"><p class="eyebrow">{{ t('business.retailLabel') }}</p><ShoppingBag :size="28" :stroke-width="1.3" aria-hidden="true" /></div><h3>{{ t('contact.consumerTitle') }}</h3><p class="lead">{{ t('contact.consumerCopy') }}</p><ul class="contact-services"><li v-for="item in t('business.retailPoints')" :key="item.title"><h4>{{ item.title }}</h4><p>{{ item.text }}</p></li></ul><div class="contact-path-actions"><StoreLinks /><RouterLink to="/support" class="text-link">{{ t('business.supportCta') }}<ArrowUpRight :size="16" aria-hidden="true" /></RouterLink><p class="content-note">{{ t('business.retailNote') }}</p></div></article>
  <article class="contact-path contact-path-trade"><div class="contact-path-top"><p class="eyebrow">{{ t('business.tradeLabel') }}</p><Boxes :size="28" :stroke-width="1.3" aria-hidden="true" /></div><h3>{{ t('contact.tradeTitle') }}</h3><p class="lead">{{ t('contact.tradeCopy') }}</p><ul class="contact-services"><li v-for="item in t('business.tradePoints')" :key="item.title"><h4>{{ item.title }}</h4><p>{{ item.text }}</p></li></ul><div class="contact-path-actions"><RouterLink to="/contact/business-enquiry?interest=1#enquiry" class="button button-dark">{{ t('business.tradeCta') }}<ArrowUpRight :size="18" aria-hidden="true" /></RouterLink><p class="content-note">{{ t('business.tradeNote') }}</p></div></article>
 </AnimatedContent>
</div></section>
<section class="section-space"><div class="container"><AnimatedContent :stagger="0.08" class="section-heading"><p class="eyebrow">{{ t('business.processLabel') }}</p><h2>{{ t('business.processTitle') }}</h2></AnimatedContent><AnimatedContent tag="ol" :stagger="0.08" class="values-grid enquiry-steps"><li v-for="(step, i) in t('business.steps')" :key="step.title" class="editorial-card editorial-card--illustrated"><EditorialCardHeader :number="`0${i + 1}`" :icon="stepIcons[i]" /><h3>{{ step.title }}</h3><p>{{ step.text }}</p></li></AnimatedContent></div></section>
<section id="enquiry" class="section-space section-muted"><div class="container enquiry-layout"><AnimatedContent :stagger="0.08" class="enquiry-intro"><div class="enquiry-intro-heading"><MessageSquareText :size="22" :stroke-width="1.4" aria-hidden="true" /><p class="eyebrow">{{ t('contact.label') }}</p></div><h2>{{ t('contact.formTitle') }}</h2><p class="lead">{{ t('contact.formCopy') }}</p><aside class="enquiry-checklist"><h3>{{ t('business.checklistTitle') }}</h3><ul><li v-for="item in t('business.checklist')" :key="item"><Check :size="17" aria-hidden="true" />{{ item }}</li></ul><p class="content-note">{{ t('business.checklistNote') }}</p></aside><p v-if="selectedProduct" class="selected-product">{{ t('common.collection') }}<strong>{{ tx(selectedProduct.name) }}</strong></p><div class="enquiry-photo"><img :src="publicAsset('/images/ceramics/craft.jpg')" :alt="t('common.imageNote')" loading="lazy" width="480" height="320" /></div></AnimatedContent>
<AnimatedContent tag="form" :stagger="0.08" v-if="!ready" class="enquiry-form" @submit.prevent="prepare"><div class="form-grid"><label>{{ t('contact.name') }}<input ref="firstField" v-model="name" name="name" autocomplete="name" required maxlength="100" /></label><label>{{ t('contact.email') }}<input v-model="email" name="email" type="email" autocomplete="email" required maxlength="254" /></label><label>{{ t('contact.company') }} <span>{{ t('contact.optional') }}</span><input v-model="company" name="company" autocomplete="organization" maxlength="150" /></label><label>{{ t('contact.interest') }}<select v-model="interest" name="interest" required><option value="" disabled>{{ t('contact.select') }}</option><option v-for="(type, i) in t('contact.types')" :key="i" :value="String(i)">{{ type }}</option></select></label><label class="full-field">{{ t('contact.quantity') }} <span>{{ t('contact.optional') }}</span><input v-model="quantity" name="quantity" :placeholder="t('contact.quantityPlaceholder')" maxlength="150" /></label><label class="full-field">{{ t('contact.message') }}<textarea v-model="message" name="message" rows="6" required maxlength="5000" :placeholder="t('contact.messagePlaceholder')" /></label></div><label class="consent-label"><input v-model="consent" type="checkbox" required /><span>{{ t('contact.consent') }}</span></label><button class="button button-dark" type="submit">{{ t('contact.prepare') }}<ArrowUpRight :size="18" /></button></AnimatedContent>
<AnimatedContent :stagger="0.08" v-else class="enquiry-result"><h3 ref="summary" tabindex="-1">{{ t('contact.ready') }}</h3><p class="lead">{{ t('contact.readyCopy') }}</p><label for="enquiry-draft" class="sr-only">{{ t('contact.draft') }}</label><textarea id="enquiry-draft" :value="draft" readonly rows="14" /><div class="button-row"><button class="button button-dark" type="button" @click="copy"><Copy :size="16" />{{ t('contact.copy') }}</button><button class="button store-button" type="button" @click="download"><Download :size="16" />{{ t('contact.download') }}</button><button class="text-button" type="button" @click="edit">{{ t('contact.edit') }}</button></div><p v-if="copyState" role="status" class="fine-print">{{ t(`contact.${copyState}`) }}</p><StoreLinks /></AnimatedContent>
</div></section></main></template>